describe('a list_sessions frame', () => {
  const listing = (store: SessionStore) => {
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const handle = createMessageHandler({} as ChatOrchestrator, store);
    return {sent, send: (raw: unknown) => handle(ws, session, raw)};
  };
  const required = new InMemorySessionStore();

  it('answers from listFor for the session user with ISO dates, and SERVER_ERROR with a ws log when it rejects', async () => {
    const seen: unknown[] = [];
    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
    const listed = listing({
      ...bound(required),
      listFor: (userId, options) => {
        seen.push({userId, options});
        return [{sessionId: 's2', createdAt: new Date(0), updatedAt: new Date(60_000), entryCount: 2}];
      },
    });
    const unlisted = listing(bound(required));
    const failing = listing({...bound(required), listFor: () => Promise.reject(new Error('database offline'))});
    const errors: Array<{category: string; fields?: Record<string, unknown>}> = [];
    const quiet = () => undefined;
    setLogger({debug: quiet, info: quiet, warn: quiet, error: (category, _message, fields) => errors.push({category, fields})});

    try {
      await listed.send({type: 'list_sessions', limit: 10, before, userId: 'u2'});
      await unlisted.send({type: 'list_sessions'});
      await failing.send({type: 'list_sessions'});
    } finally {
      setLogger();
    }

    expect({seen, listed: listed.sent, unlisted: unlisted.sent, failing: failing.sent.map(f => f.type === 'error' && f.code), errors}).toEqual({
      seen: [{userId: 'u1', options: {limit: 10, before}}],
      listed: [
        {
          type: 'session_list',
          sessions: [{sessionId: 's2', createdAt: '1970-01-01T00:00:00.000Z', updatedAt: '1970-01-01T00:01:00.000Z', entryCount: 2}],
        },
      ],
      unlisted: [{type: 'session_list', sessions: []}],
      failing: ['SERVER_ERROR'],
      errors: [{category: 'ws', fields: expect.objectContaining({userId: 'u1', error: 'database offline'})}],
    });
  });
});

// The five required members only, so a test decides whether listFor exists.
function bound(inner: InMemorySessionStore): SessionStore {
  return {
    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    get: sessionId => inner.get(sessionId),
    delete: sessionId => inner.delete(sessionId),
    count: () => inner.count(),
    clear: () => inner.clear(),
  };
}
EOF
